{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Hydroxybupropion, a chlorophenyl-containing analogue with a secondary amine and similar lipophilicity, achieves rapid equilibration across the BBB with Kp,uu 1.7 in rat microdialysis, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Amphetamine, a simple chiral phenethylamine, is confirmed to cross the BBB and bind CNS targets after systemic administration in rats, supporting CNS access for the query's chiral phenethylamine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Dexketoprofen, despite being a carboxylic acid, was detected in human CSF after systemic dosing, demonstrating that molecules with the chiral methyl-aryl motif can achieve meaningful CNS exposure; the neutral, more lipophilic query is expected to be at least as permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "AH-7921, a benzamide with a chlorophenyl group, shows a rat brain-to-plasma ratio of 16.6, directly supporting that chlorophenyl amide-containing structures can achieve high CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "JJC 4-077, an amide-containing compound with a chlorophenyl group, entered the brain quickly and showed high brain penetration after i.v. administration, supporting the query's CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is neutral, moderately lipophilic, and within passive BBB-permeability ranges. Multiple high-transfer experimental analogues—including chlorophenyl amides, chiral phenethylamines, and related CNS-penetrant drugs—show direct brain/CSF uptake, Kp,uu >1, or high brain-to-plasma ratios. No contradictory evidence was identified. Therefore, meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct experimental BBB measurement for the exact query molecule.",
    "No explicit efflux-transporter data for the query, though the physicochemical prior and analogue evidence suggest low efflux liability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

